 75	export function resolveEdgeRequest(req, { trustedProxies = [], forwardedHop = 0, requireForwardedHttps = false } = {}) {
 76	  if (!Number.isSafeInteger(forwardedHop) || forwardedHop < 0) throw new TypeError('forwardedHop must be a non-negative safe integer');
