 82	  if (forwarded != null) {
 83	    if (req.headers?.['x-forwarded-proto'] != null) throw new TypeError('mixed forwarding headers');
 84	    const chain = parseForwarded(forwarded);
 85	    if (forwardedHop >= chain.length) throw new TypeError('invalid forwarding chain');
 86	    const selected = chain[chain.length - 1 - forwardedHop];
 87	    if (requireForwardedHttps && selected.proto !== 'https') throw new TypeError('forwarded HTTPS required');
 88	    return { address: selected.address, transport: selected.proto, proxied: true };
 89	  }
 90	  if (typeof xff !== 'string' || xff.length === 0 || xff.length > 512) throw new TypeError('invalid forwarding chain');
 91	  const chain = xff.split(',').map((part) => address(part.trim()));
 92	  if (chain.length > 16 || forwardedHop >= chain.length) throw new TypeError('invalid forwarding chain');
 93	  const proto = req.headers?.['x-forwarded-proto'];
 94	  if (typeof proto !== 'string' || !['https', 'http'].includes(proto)) throw new TypeError('invalid forwarded protocol');
 95	  if (requireForwardedHttps && proto !== 'https') throw new TypeError('forwarded HTTPS required');
 96	  return { address: chain[chain.length - 1 - forwardedHop], transport: proto, proxied: true };
